<script setup lang="ts">
import {onMounted,onBeforeUnmount,ref,watch,nextTick} from 'vue';
import type * as Monaco from 'monaco-editor/editor';
import {api} from '../api';
import {configOffset,configByteOffset,type ConfigProject,type Compilation,type Completion,type Span} from '../configuration';
import {completionContext} from '../configurationNavigation';
const props=defineProps<{project:ConfigProject;file:string;compilation:Compilation|null;readOnly:boolean;session:number}>();
const emit=defineEmits<{change:[file:string,value:string];navigate:[span:Span];format:[];rename:[file:string,offset:number];error:[message:string]}>();
const host=ref<HTMLElement|null>(null),loading=ref(true),failed=ref(''),cursor=ref('Ln 1, Col 1');
let monaco:typeof Monaco,editor:Monaco.editor.IStandaloneCodeEditor|undefined,observer:ResizeObserver|undefined,disposed=false,syncing=false;
const models=new Map<string,Monaco.editor.ITextModel>(),states=new Map<string,Monaco.editor.ICodeEditorViewState>();
const disposables:Monaco.IDisposable[]=[];const workspace=`lce-${crypto.randomUUID()}`;
const fileOf=(model:Monaco.editor.ITextModel)=>decodeURIComponent(model.uri.path.slice(1));
const owns=(model:Monaco.editor.ITextModel)=>model.uri.authority===workspace;
function modelFor(file:string){let model=models.get(file);if(!model){model=monaco.editor.createModel(props.project.files[file]||'','lce',monaco.Uri.from({scheme:'lce',authority:workspace,path:'/'+file}));models.set(file,model);model.onDidChangeContent(()=>{if(!syncing)emit('change',file,model!.getValue())})};return model}
function synchronize(){if(!editor)return;const previous=editor.getModel();if(previous){const state=editor.saveViewState();if(state)states.set(fileOf(previous),state)};syncing=true;
 for(const [file,model]of models){if(!(file in props.project.files)){if(editor.getModel()===model)editor.setModel(null);model.dispose();models.delete(file);states.delete(file)}else if(model.getValue()!==props.project.files[file]){model.pushStackElement();model.pushEditOperations([],[{range:model.getFullModelRange(),text:props.project.files[file]}],()=>null);model.pushStackElement()}}
 const model=modelFor(props.file);editor.setModel(model);const state=states.get(props.file);if(state)editor.restoreViewState(state);syncing=false;markers();editor.layout();}
function markers(){if(!monaco)return;for(const [file,model]of models){monaco.editor.setModelMarkers(model,'lce',(props.compilation?.diagnostics||[]).filter(d=>d.file===file).map(d=>{const text=model.getValue(),start=model.getPositionAt(configOffset(text,d.start)),end=model.getPositionAt(configOffset(text,d.end));return {startLineNumber:start.lineNumber,startColumn:start.column,endLineNumber:end.lineNumber,endColumn:end.lineNumber===start.lineNumber?Math.max(end.column,start.column+1):end.column,message:`${d.path?d.path+': ':''}${d.message}`,code:d.code,severity:monaco.MarkerSeverity.Error}}))}}
function offset(){return editor?.getModel()?.getOffsetAt(editor.getPosition()!)||0}
async function reveal(span:Span){await nextTick();if(!editor)return;synchronize();const model=editor.getModel()!,text=model.getValue(),start=model.getPositionAt(configOffset(text,span.start)),end=model.getPositionAt(configOffset(text,span.end));editor.setSelection(new monaco.Range(start.lineNumber,start.column,end.lineNumber,end.column));editor.revealPositionInCenter(start);editor.focus()}
function insert(text:string){if(!editor)return;editor.executeEdits('lce-insert',[{range:editor.getSelection()!,text,forceMoveMarkers:true}]);editor.focus()}
function suggest(){editor?.focus();editor?.trigger('lce','editor.action.triggerSuggest',{})}
async function definition(){if(!editor)return;const model=editor.getModel()!,version=model.getVersionId();try{const span=await api<Span>('/configuration/definition','POST',{project:props.project,file:props.file,offset:configByteOffset(model.getValue(),offset())});if(!disposed&&!model.isDisposed()&&model===editor?.getModel()&&version===model.getVersionId())emit('navigate',span)}catch(e){emit('error',(e as Error).message)}}
defineExpose({offset,reveal,insert,suggest,definition});
onMounted(async()=>{try{
 ({monaco}=await import('../monacoConfiguration'));if(disposed||!host.value)return;
 editor=monaco.editor.create(host.value,{theme:'lce-studio',language:'lce',fontSize:13,fontFamily:'ui-monospace, SFMono-Regular, Consolas, monospace',lineHeight:21,tabSize:2,insertSpaces:true,readOnly:props.readOnly,minimap:{enabled:false},scrollBeyondLastLine:false,automaticLayout:false,wordWrap:'off',padding:{top:14,bottom:14},bracketPairColorization:{enabled:true},guides:{bracketPairs:true},folding:true,ariaLabel:'Configuration source',fixedOverflowWidgets:true});
 disposables.push(editor.onDidChangeCursorPosition(e=>cursor.value=`Ln ${e.position.lineNumber}, Col ${e.position.column}`));
 disposables.push(monaco.languages.registerCompletionItemProvider('lce',{triggerCharacters:['.'],async provideCompletionItems(model,position,context,token){if(!owns(model))return {suggestions:[]};const version=model.getVersionId(),snapshot=JSON.stringify(props.project),word=model.getWordUntilPosition(position),range=new monaco.Range(position.lineNumber,word.startColumn,position.lineNumber,word.endColumn),ctx=completionContext(model.getValue(),model.getOffsetAt(position));
 try{const values=await api<Completion[]>('/configuration/complete','POST',{project:JSON.parse(snapshot),file:fileOf(model),...ctx});if(disposed||token.isCancellationRequested||model.isDisposed()||version!==model.getVersionId()||snapshot!==JSON.stringify(props.project))return {suggestions:[]};const snippets=ctx.declaration?[]:[{label:'behavior',insertText:'behavior ${1:Component} {\n  name = "${2:Component name}";\n  behavior = {\n    inputs = [];\n    outputs = [];\n    nodes = [];\n    bindings = {};\n  };\n}'},{label:'experiment',insertText:'experiment ${1:Example} {\n  target = target(${2:subject.Component});\n  scenario = { inputs = {}; };\n  expect = { "${3:outputs.result.boolean}" = ${4:true}; };\n}'},{label:'import',insertText:'import "${1:component.lce}" as ${2:subject};'},{label:'fixture',insertText:'fixture ${1:request} = { ${2} };'}].map(v=>({...v,kind:monaco.languages.CompletionItemKind.Snippet,detail:'LCE template',range,insertTextRules:monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet}));return {suggestions:[...snippets,...values.map(v=>({label:v.label,kind:v.kind==='field'?monaco.languages.CompletionItemKind.Field:v.kind==='constructor'?monaco.languages.CompletionItemKind.Function:monaco.languages.CompletionItemKind.Reference,detail:[v.type,v.required?'required':'',v.detail].filter(Boolean).join(' · '),insertText:v.kind==='field'?`${v.label} = \${1};`:v.kind==='constructor'?v.label.replace('()','(\${1})'):v.label,insertTextRules:monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,range}))]}}catch{return {suggestions:[]}}}}));
 disposables.push(monaco.languages.registerDocumentSymbolProvider('lce',{provideDocumentSymbols(model){if(!owns(model))return [];return (props.compilation?.documents.find(d=>d.file===fileOf(model))?.declarations||[]).map(d=>{const start=model.getPositionAt(configOffset(model.getValue(),d.start)),end=model.getPositionAt(configOffset(model.getValue(),d.end));const range=new monaco.Range(start.lineNumber,start.column,end.lineNumber,end.column);return {name:d.name,detail:d.kind,kind:monaco.languages.SymbolKind.Class,tags:[],range,selectionRange:range}})}}));
 editor.addAction({id:'lce-definition',label:'Go to LCE definition',keybindings:[monaco.KeyCode.F12],contextMenuGroupId:'navigation',run:definition});
 editor.addAction({id:'lce-rename',label:'Rename LCE declaration safely',keybindings:[monaco.KeyCode.F2],contextMenuGroupId:'modification',run:()=>emit('rename',props.file,configByteOffset(editor!.getModel()!.getValue(),offset()))});
 editor.addAction({id:'lce-format',label:'Format LCE document',keybindings:[monaco.KeyMod.Shift|monaco.KeyMod.Alt|monaco.KeyCode.KeyF],contextMenuGroupId:'modification',run:()=>emit('format')});
 editor.addAction({id:'lce-compile',label:'Show suggestions',keybindings:[monaco.KeyMod.CtrlCmd|monaco.KeyCode.Space],run:suggest});
 observer=new ResizeObserver(()=>editor?.layout());observer.observe(host.value);synchronize();loading.value=false;
 }catch(e){loading.value=false;failed.value=(e as Error).message;emit('error','Code editor could not load: '+failed.value)}});
watch(()=>[props.file,props.project.files],synchronize,{deep:true,flush:'post'});
watch(()=>props.compilation,markers);
watch(()=>props.readOnly,value=>editor?.updateOptions({readOnly:value}));
watch(()=>props.session,()=>{editor?.setModel(null);for(const m of models.values())m.dispose();models.clear();states.clear();synchronize()});
onBeforeUnmount(()=>{disposed=true;observer?.disconnect();for(const d of disposables)d.dispose();editor?.dispose();for(const m of models.values())m.dispose()});
</script>
<template><div class="code-editor-shell"><p v-if="loading" role="status" class="editor-loading">Loading code editor…</p><p v-if="failed" role="alert" class="editor-loading">Editor unavailable: {{failed}}. Export your source before reloading.</p><div ref="host" class="monaco-host"/><footer class="editor-status"><span>{{cursor}}</span><span>Spaces: 2</span><span>UTF-8</span><span>LCE 1.0</span></footer></div></template>
<style scoped>
.code-editor-shell{position:relative;min-width:0;overflow:hidden;background:#18232f;border:1px solid #334858;display:flex;flex-direction:column}.monaco-host{height:clamp(380px,62vh,1000px);min-width:0;width:100%;text-align:left}.editor-status{background:#244958;color:#e3f2f3;padding:5px 12px;display:flex;justify-content:flex-end;flex-wrap:wrap;gap:16px;font:11px/1.4 ui-monospace,monospace}.editor-loading{color:#d6e4ea;padding:12px}.code-editor-shell :deep(.monaco-editor){outline:none!important}@media(max-width:700px){.monaco-host{height:55vh;min-height:320px}}
</style>
